import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";
import type * as TypeScript from "typescript";

import {
  CANONICAL_LABELS,
  POLICY_LABELS,
  SPAN_ACTIONS,
  type OpenMedContractSpan,
  type OpenMedSpan,
} from "../../js/openmedkit-web/src/index";

// Generated by scripts/codegen/emit_ts_types.py from openmed/core/schemas/json/.
const rootDir = fileURLToPath(new URL("../..", import.meta.url));
const SCHEMA_DIR = join(rootDir, "openmed", "core", "schemas", "json");
const PACKAGE_DIR = join(rootDir, "js", "openmedkit-web");
const TYPES_PATH = resolve(PACKAGE_DIR, "src", "types.ts");
const GUARD_PATH = resolve(PACKAGE_DIR, "src", "contract-guards.ts");
const GENERATED_PATH = resolve(PACKAGE_DIR, "src", "generated", "contract-types.ts");
const EXAMPLES_PATH = join(
  rootDir,
  "tests",
  "fixtures",
  "contracts",
  "core_contract_examples.json",
);
// In-memory only: never written to disk.
const EXAMPLES_MODULE = resolve(PACKAGE_DIR, "src", "__contract_examples__.ts");
// Resolve the compiler from the web package so its pinned devDependency is used.
const ts = createRequire(join(PACKAGE_DIR, "package.json"))(
  "typescript",
) as typeof TypeScript;
const SPAN_INTERFACE = "export interface OpenMedContractSpan {\n";
// TS2344: type does not satisfy the constraint (the `AssertTrue` guard).
const CONSTRAINT_NOT_SATISFIED = 2344;

interface SpanSchema {
  properties: Record<string, { enum?: string[] }>;
}

async function spanSchema(): Promise<SpanSchema> {
  return JSON.parse(
    await readFile(join(SCHEMA_DIR, "span.schema.json"), "utf8"),
  ) as SpanSchema;
}

function compilerOptions(): TypeScript.CompilerOptions {
  const configPath = join(PACKAGE_DIR, "tsconfig.json");
  const config = ts.readConfigFile(configPath, ts.sys.readFile);
  assert.equal(config.error, undefined);
  const parsed = ts.parseJsonConfigFileContent(
    config.config,
    ts.sys,
    dirname(configPath),
  );
  return { ...parsed.options, noEmit: true };
}

/** Type-check `root` with in-memory file contents; return its own diagnostics. */
function diagnosticsFor(
  root: string,
  files: ReadonlyMap<string, string> = new Map(),
  extraOptions: TypeScript.CompilerOptions = {},
): readonly TypeScript.Diagnostic[] {
  const options = { ...compilerOptions(), ...extraOptions };
  const host = ts.createCompilerHost(options, true);
  const readSourceFile = host.getSourceFile.bind(host);
  const fileExists = host.fileExists.bind(host);
  host.fileExists = (fileName) => files.has(resolve(fileName)) || fileExists(fileName);
  host.getSourceFile = (fileName, languageVersion, onError, shouldCreate) => {
    const text = files.get(resolve(fileName));
    if (text !== undefined) {
      return ts.createSourceFile(fileName, text, languageVersion, true);
    }
    return readSourceFile(fileName, languageVersion, onError, shouldCreate);
  };
  const program = ts.createProgram([root], options, host);
  assert.ok(program.getSourceFile(root), "type-check root was not loaded");
  return ts
    .getPreEmitDiagnostics(program)
    .filter((item) => item.file !== undefined && resolve(item.file.fileName) === root);
}

/** Type-check the guard module, optionally rewriting the generated module first. */
function guardDiagnostics(
  rewriteGenerated?: (source: string) => string,
): readonly TypeScript.Diagnostic[] {
  if (rewriteGenerated === undefined) {
    return diagnosticsFor(GUARD_PATH);
  }
  const original = ts.sys.readFile(GENERATED_PATH);
  assert.ok(original !== undefined);
  return diagnosticsFor(GUARD_PATH, new Map([[GENERATED_PATH, rewriteGenerated(original)]]));
}

type Examples = Record<string, Record<string, unknown>[]>;

/** Render the shared schema examples as constants typed by the generated types. */
async function examplesModule(mutate?: (examples: Examples) => void): Promise<string> {
  const fixture = JSON.parse(await readFile(EXAMPLES_PATH, "utf8")) as {
    examples: Examples;
  };
  mutate?.(fixture.examples);
  const lines = ['import type * as Contract from "./generated/contract-types";'];
  for (const [schema, records] of Object.entries(fixture.examples)) {
    const { title } = JSON.parse(
      await readFile(join(SCHEMA_DIR, `${schema}.schema.json`), "utf8"),
    ) as { title: string };
    const typeName = `OpenMedContract${title.replace(/^OpenMed/, "")}`;
    records.forEach((record, index) => {
      lines.push(
        `export const ${schema}_${index}: Contract.${typeName} = ${JSON.stringify(record)};`,
      );
    });
  }
  return `${lines.join("\n")}\n`;
}

async function examplesDiagnostics(
  mutate?: (examples: Examples) => void,
): Promise<readonly TypeScript.Diagnostic[]> {
  const source = await examplesModule(mutate);
  return diagnosticsFor(EXAMPLES_MODULE, new Map([[EXAMPLES_MODULE, source]]));
}

function rewriteSpanInterface(
  source: string,
  rewrite: (body: string) => string,
): string {
  const start = source.indexOf(SPAN_INTERFACE);
  assert.ok(start >= 0, "generated span interface is missing");
  const bodyStart = start + SPAN_INTERFACE.length;
  const end = source.indexOf("\n}\n", bodyStart);
  assert.ok(end > bodyStart);
  const body = source.slice(bodyStart, end);
  const rewritten = rewrite(body);
  assert.notEqual(rewritten, body, "synthetic drift did not change the span type");
  return source.slice(0, bodyStart) + rewritten + source.slice(end);
}

test("exported label, policy and action lists equal the span schema enums", async () => {
  const schema = await spanSchema();
  assert.deepEqual([...CANONICAL_LABELS], schema.properties.canonical_label?.enum);
  assert.deepEqual([...POLICY_LABELS], schema.properties.policy_label?.enum);
  assert.deepEqual([...SPAN_ACTIONS], schema.properties.action?.enum);
});

test("hand-written and generated span types accept the same record", () => {
  const record: OpenMedContractSpan = {
    schema_version: 1,
    doc_id: "synthetic-doc",
    start: 0,
    end: 4,
    text_hash: `hmac-sha256:${"0".repeat(64)}`,
    entity_type: "first_name",
    canonical_label: "FIRST_NAME",
    policy_label: "SENSITIVE_ATTRIBUTE",
    regulatory_tags: [],
    score: null,
    detector: null,
    evidence: {},
    action: "redact",
    replacement: null,
    reversible_id: null,
    section: null,
    metadata: {},
  };
  const handWritten: OpenMedSpan = record;
  const generated: OpenMedContractSpan = handWritten;
  assert.deepEqual(generated, record);
});

test("the span contract guard type-checks against the committed module", () => {
  assert.deepEqual(guardDiagnostics().map((item) => item.code), []);
});

test("types.ts compiles for consumers that reject unused locals", () => {
  // The browser extension compiles the web sources with these options.
  const strict = { noUnusedLocals: true, noUnusedParameters: true };
  assert.deepEqual(
    diagnosticsFor(TYPES_PATH, new Map(), strict).map((item) => item.code),
    [],
  );
});

test("an added required schema property fails the span contract guard", () => {
  const diagnostics = guardDiagnostics((source) =>
    rewriteSpanInterface(source, (body) => `  synthetic_field: string;\n${body}`),
  );
  assert.ok(diagnostics.some((item) => item.code === CONSTRAINT_NOT_SATISFIED));
});

test("a changed schema field type fails the span contract guard", () => {
  const diagnostics = guardDiagnostics((source) =>
    rewriteSpanInterface(source, (body) =>
      body.replace("  score: number | null;", "  score: number;"),
    ),
  );
  assert.ok(diagnostics.some((item) => item.code === CONSTRAINT_NOT_SATISFIED));
});

test("every shared schema example satisfies its generated type", async () => {
  const source = await examplesModule();
  assert.ok(source.includes(": Contract.OpenMedContractDataResidencyAttestation = "));
  assert.deepEqual((await examplesDiagnostics()).map((item) => item.code), []);
});

test("generated types reject examples that break the schema", async () => {
  const undeclared = await examplesDiagnostics((examples) => {
    examples.span![0]!.synthetic_extra = true;
  });
  const missing = await examplesDiagnostics((examples) => {
    delete examples.code![0]!.system;
  });
  const wrongType = await examplesDiagnostics((examples) => {
    examples.audit![0]!.timestamp = 5;
  });
  const wrongEnum = await examplesDiagnostics((examples) => {
    examples.action![0]!.action = "synthetic_action";
  });
  for (const diagnostics of [undeclared, missing, wrongType, wrongEnum]) {
    assert.ok(diagnostics.length > 0);
  }
});
